#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    long long l, r;
    cin >> a >> b >> l >> r;

    if (r - l + 1 >= 2LL * (a + b)) {
        cout << (a <= b ? a + 1 : 2 * a - b) << "\n";
        return 0;
    }

    string pattern;
    for (int i = 0; i < a; i++) {
        pattern += ('a' + i);
    }

    l--;
    r--;

    int minDistinctChars = 26;

    for (int startIdx = 0; startIdx < 26; startIdx++) {
        for (int secondIdx = a; secondIdx < 26; secondIdx++) {
            string currentStr = pattern;
            for (int i = 0; i < b; i++) {
                currentStr += ('a' + startIdx);
            }
            std::set<int> usedCharsSet;
            // Extract last a characters
            for (int i = (int)currentStr.size() - a; i < (int)currentStr.size(); i++) {
                usedCharsSet.insert(currentStr[i] - 'a');
            }
            int nextCharCode = 0;
            for (int i = 0; i < a; i++) {
                while (usedCharsSet.count(nextCharCode)) {
                    nextCharCode++;
                }
                currentStr += ('a' + nextCharCode);
                nextCharCode++;
            }
            for (int i = 0; i < b; i++) {
                currentStr += ('a' + secondIdx);
            }
            int totalLen = (int)currentStr.size();
            usedCharsSet.clear();
            for (long long i = l % totalLen; i != (r + 1) % totalLen; i = (i + 1) % totalLen) {
                usedCharsSet.insert(currentStr[i] - 'a');
            }
            if ((int)usedCharsSet.size() < minDistinctChars) {
                minDistinctChars = (int)usedCharsSet.size();
            }
        }
    }
    cout << minDistinctChars << "\n";

    return 0;
}
